/*
 * A040107  Primes p such that x^4 = 6 has a solution mod p.
 * https://oeis.org/A040107
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = the nth prime p such that x⁴ = 6 has a solution mod p
 *            (OEIS A040107). The sequence is generated by testing primes one
 *            by one and keeping those that satisfy the fourth‑power residue
 *            condition
 * Range:     u8 n <= 19, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

/* Modulo exponentiation.  Result is cast to seq_t so that either
   built‑in integer types or the arbitrary‑precision type provided by
   the build environment can be returned. */
static seq_t mod_pow_u64(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t result = 1 % mod;
    base %= mod;
    while (exp > 0) {
        if (exp & 1u)
            result = (unsigned __int128)result * base % mod;
        exp >>= 1u;
        if (exp)
            base = (unsigned __int128)base * base % mod;
    }
    return (seq_t)result;
}

/* Simple deterministic primality test using trial division by all
   previously found primes.  It works for all primes needed here (up
   to a few hundred thousand). */
static bool is_prime_test(uint64_t n,
                          const uint64_t *primes, size_t primes_len)
{
    if (n < 2) return false;
    for (size_t i = 0; i < primes_len; ++i) {
        uint64_t p = primes[i];
        if (p > n / p) break;        /* p*p > n */
        if (n % p == 0) return false;
    }
    return true;
}

/* Main sequence function: a(idx_t n) */
seq_t a(idx_t n)
{
    if (n == 0) return 0;            /* offset is 1 */

    /* static cache of computed sequence terms */
    static seq_t *cache   = NULL;
    static size_t cache_len = 0, cache_cap = 0;

    /* static list of primes used for primality testing */
    static uint64_t *primes = NULL;
    static size_t primes_len = 0, primes_cap = 0;

    /* next number to test for primality */
    static uint64_t next_candidate = 2;

    /* initialise prime list with 2 */
    if (primes_len == 0) {
        primes_cap = 8;
        primes = (uint64_t *)realloc(NULL, primes_cap * sizeof(uint64_t));
        primes[0] = 2;
        primes_len = 1;
    }

    /* generate terms until we have at least n of them */
    while (cache_len < (size_t)n) {
        /* test current candidate for primality */
        if (is_prime_test(next_candidate, primes, primes_len)) {
            /* store prime for future divisibility checks */
            if (primes_len == primes_cap) {
                primes_cap = primes_cap * 2;
                uint64_t *tmp = (uint64_t *)realloc(primes,
                                                    primes_cap * sizeof(uint64_t));
                primes = tmp;
            }
            primes[primes_len++] = next_candidate;

            /* check whether x⁴ = 6 has a solution modulo this prime */
            bool good = false;
            if (next_candidate == 2 || next_candidate == 3) {
                /* 6 ≡ 0 mod 2,3 → x = 0 satisfies the congruence */
                good = true;
            } else {
                uint64_t p   = next_candidate;
                uint64_t exp = ((p - 1) & 3) == 0 ? (p - 1) / 4 : (p - 1) / 2;
                seq_t  r    = mod_pow_u64(6, exp, p);
                good = (r == (seq_t)1);
            }

            if (good) {
                /* append to cache */
                if (cache_len == cache_cap) {
                    cache_cap = cache_cap ? cache_cap * 2 : 8;
                    seq_t *tmp = (seq_t *)realloc(cache,
                                                  cache_cap * sizeof(seq_t));
                    cache = tmp;
                }
                cache[cache_len++] = (seq_t)next_candidate;
            }
        }

        /* advance to the next odd candidate after 2 */
        if (next_candidate == 2)
            next_candidate = 3;
        else
            next_candidate += 2;
    }

    return cache[n - 1];
}
